{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--muted:#95a3b3;--accent:#c7a76b;--glass:rgba(255,255,255,0.04)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;color:#e6eef6;background:linear-gradient(180deg,var(--bg),#07101a);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#10212a,var(--accent));display:flex;align-items:center;justify-content:center;color:#08151a;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-size:14px}
    nav a:hover{color:#fff}
    .btn-cta{background:var(--accent);color:#07101a;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:600}
    main{padding:36px}
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
    .hero .panel{background:linear-gradient(180deg,var(--card),#07101a);padding:28px;border-radius:12px;box-shadow:0 6px 30px rgba(2,6,23,0.6)}
    .eyebrow{color:var(--accent);font-weight:700;font-size:13px}
    h1{margin:8px 0 12px;font-size:28px}
    p.lead{color:var(--muted);line-height:1.6}
    .tiers{display:flex;gap:18px;margin-top:22px}
    .tier{flex:1;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:20px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
    .tier h3{margin:0 0 8px}
    .price{font-size:20px;color:var(--accent);font-weight:700}
    .features{color:var(--muted);font-size:14px;margin-top:8px}
    .muted-note{color:var(--muted);font-size:13px;margin-top:12px}
    .gallery{margin-top:26px;display:flex;gap:12px;align-items:center}
    .testimonial{background:var(--glass);padding:14px;border-radius:10px;flex:1;color:#dfeefb}
    .badge{display:inline-flex;align-items:center;gap:8px;margin-left:10px}
    .badges{display:flex;gap:8px;margin-top:12px}
    .badge-svg{width:36px;height:36px;border-radius:6px;background:#071826;display:grid;place-items:center;color:var(--accent);font-weight:700}
    footer{padding:26px;border-top:1px solid rgba(255,255,255,0.02);color:var(--muted);display:flex;justify-content:space-between}
    .faq{margin-top:20px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:10px}
    .tooltip{position:relative}
    .tooltip .tip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#06202a;color:#e6eef6;padding:8px;border-radius:6px;font-size:13px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .18s}
    .tooltip:hover .tip{opacity:1}
    /* pattern fallback */
    .pattern-wrap{background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.tiers{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Aromatherapy practice in {{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Sanctum</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends Lab</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html" style="color:#fff;font-weight:700">Investment</a>
      <a href="about.html">Who I Am</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach Out</a>
      <a class="btn-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>
  <main>
    <section class="hero pattern-wrap">
      <div class="panel">
        <div class="eyebrow">Investment & Plans</div>
        <h1>Intentional scent guidance — plans shaped to fit your rhythm</h1>
        <p class="lead">Each offering is designed to center around sensory clarity and practical at-home rituals. Sessions and plans are guided, safety-aware, and tailored to your life. Results may vary; these services may support well-being, not treat conditions.</p>
        <div class="tiers" aria-label="pricing tiers">
          <div class="tier">
            <h3>Essence Intensive</h3>
            <div class="price">From $240</div>
            <div class="features">90–120 minute deep session with bespoke blend formulation, hands-on scent mapping, and a take-home roll-on.
            </div>
            <div class="muted-note">Best for clients seeking an immersive single-session reset.</div>
          </div>
          <div class="tier">
            <h3>Seasonal Palette</h3>
            <div class="price">From $380</div>
            <div class="features">Three-session sequence across 8–12 weeks. Includes blend updates and short check-ins. Ideal for ongoing adaptations.</div>
            <div class="muted-note">Payment plans available on request.</div>
          </div>
          <div class="tier">
            <h3>Continuity Plan</h3>
            <div class="price">Monthly from $95</div>
            <div class="features">Monthly support for blend refreshes, priority booking, and seasonal suggestions. Designed for steady scent care.</div>
            <div class="muted-note">Cancellation-friendly; pause anytime.</div>
          </div>
        </div>
        <div style="margin-top:18px">
          <a class="btn-cta" href="{{PRIMARY_CTA_URL}}">Schedule your session</a>
        </div>
      </div>
      <aside style="padding:28px">
        <div style="background:linear-gradient(180deg,#071826,rgba(255,255,255,0.02));padding:18px;border-radius:12px;color:var(--muted)">
          <strong style="color:#fff">What's included</strong>
          <ul style="margin:12px 0 0;padding-left:16px;color:var(--muted)">
            <li>Pre-session questionnaire and intake</li>
            <li>Personalized blend formula and safety notes</li>
            <li>Mixing guide, dilution chart, patch test instructions</li>
          </ul>
          <div style="margin-top:12px;font-size:13px">Sessions are safety-forward. We always discuss pregnancy, medication, and pet considerations during intake.</div>
        </div>

        <div class="gallery">
          <div class="testimonial" id="testi-box">"I left with a blend that really suits my evenings — gentle and grounded." — K.
            <div class="badges">
              <div class="tooltip"><div class="badge-svg">CE</div><div class="tip">Certified Aromatherapist (non-medical)</div></div>
              <div class="tooltip"><div class="badge-svg">SF</div><div class="tip">Safety-first formulations</div></div>
            </div>
          </div>
        </div>
      </aside>
    </section>

    <section class="faq" aria-labelledby="faq-title">
      <h3 id="faq-title">Common questions & safety notes</h3>
      <p><strong>Do these sessions treat medical conditions?</strong> — No. Services are not a substitute for medical care. Language such as "may support" is used to reflect possible outcomes, not clinical claims.</p>
      <p><strong>Patch testing & dilution</strong> — You will receive dilution guidance and a recommended patch-test before introducing new blends to skin. For facial or mucous contact we advise extra caution.</p>
      <p><strong>Pregnancy & nursing</strong> — Some oils are not recommended during pregnancy. Discuss pregnancy, breastfeeding, and medication during intake so we can adapt blends safely.</p>
      <p><strong>Pets</strong> — Certain essential oils can affect animals. We provide pet-safe options and alternatives if you share space with sensitive pets.</p>
      <p><strong>Refunds & rescheduling</strong> — See booking terms on the Reserve page. Deposits apply to hold appointments.</p>
    </section>

    <section style="margin-top:18px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:16px">
        <div>
          <h4>Ready to begin?</h4>
          <p class="muted-note">Pick your plan and book a time for a guided exploration of scent and routine.</p>
        </div>
        <div>
          <a class="btn-cta" href="book.html">Reserve an Intensive</a>
        </div>
      </div>
    </section>

  </main>
  <footer>
    <div>Contact: <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a></div>
    <div style="color:var(--muted)">&copy; <span id="year"></span> {{BUSINESS_NAME}}</div>
  </footer>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    // Rotating testimonials and badge tooltips
    (function(){
      var testiBox = document.getElementById('testi-box');
      var testimonials = [
        {quote:'"Breathable, precise, and calm—my sleep shifted." — A.', badges:['Certified Aromatherapist','Client-centered safety']},
        {quote:'"A practical roll-on that travels; I use it after long days." — M.', badges:['Practice-reviewed','Safety-first']},
        {quote:'"The seasonal follow-up helped me refine a morning ritual." — S.', badges:['Ongoing support','Small-batch blends']}
      ];
      var idx=0;
      setInterval(function(){
        idx=(idx+1)%testimonials.length;
        testiBox.firstChild.textContent = testimonials[idx].quote + ' ';
      },4500);
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Who I Am — Practitioner — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#071822;--accent:#b78e55;--muted:#98adbf}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,var(--bg),#021015);color:#e9f2f8}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 30px}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(145deg,#0b222a,var(--accent));display:grid;place-items:center;font-weight:700}
    nav a{color:var(--muted);margin:0 10px;text-decoration:none}
    .hero{padding:40px;display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
    .bio{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:22px;border-radius:12px}
    h1{margin-top:0}
    .approach{margin-top:16px;color:var(--muted)}
    .proof{margin-top:18px;display:flex;gap:12px;align-items:center}
    .badge-mini{width:44px;height:44px;border-radius:8px;background:#06242b;display:grid;place-items:center;color:var(--accent)}
    .what{margin-top:22px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:10px}
    .expect{margin-top:18px}
    .cta{display:flex;justify-content:space-between;align-items:center;margin-top:20px}
    .btn-ghost{border:1px solid rgba(255,255,255,0.06);padding:10px 12px;border-radius:8px;color:var(--muted);text-decoration:none}
    .btn-cta{background:var(--accent);color:#021015;padding:10px 12px;border-radius:8px;text-decoration:none;font-weight:600}
    .pattern{background-image:url('assets/img/pattern.svg');background-size:56px}
    .rotate-card{background:linear-gradient(180deg,#07131a,rgba(255,255,255,0.01));padding:12px;border-radius:10px}
    @media(max-width:900px){.hero{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">AR</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Aromatherapy crafted in {{CITY}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Sanctum</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends Lab</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html" style="color:#fff;font-weight:700">Who I Am</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <section class="hero pattern">
      <div class="bio">
        <h1>Practitioner & curious guide</h1>
        <p class="approach">I work with aromatic plants to compose simple rituals and blends that may support ease, focus, and rootedness. My approach is attentive: we map personal history, sensory preference, and safety constraints before blending.</p>
        <div class="proof">
          <div class="rotate-card" id="proof-rotator">"A thoughtful consultation that actually fit my life." — R.</div>
          <div style="display:flex;flex-direction:column;gap:8px">
            <div class="badge-mini tooltip">C
              <div class="tip" style="position:absolute;background:#031017;color:#dff3fc;padding:8px;border-radius:6px;display:none">Continuing education in aroma safety</div>
            </div>
            <div class="badge-mini">S</div>
          </div>
        </div>

        <div class="what">
          <h3>How I work</h3>
          <ol style="color:var(--muted)">
            <li>Intake & scent preferences</li>
            <li>Safety review (meds, pregnancy, pets)</li>
            <li>Blend formulation and dilution guidance</li>
            <li>At-home ritual planning and follow-up</li>
          </ol>
        </div>

        <div class="expect">
          <h3>What to expect</h3>
          <p class="approach">Sessions are practical and sensory. You leave with clear dilution charts, patch-test steps, and a simple ritual to try over the next week. Outcomes vary; offerings are framed to "may support" rather than promise.</p>
        </div>

      </div>

      <aside style="padding:20px;display:flex;flex-direction:column;gap:14px">
        <div style="background:linear-gradient(180deg,#062427,rgba(255,255,255,0.02));padding:14px;border-radius:12px">
          <strong>Credentials</strong>
          <p style="color:var(--muted);margin:8px 0">Formal aromatherapy study, safety-focused continuing education, small-batch blending experience.</p>
        </div>

        <div style="background:linear-gradient(180deg,#07131a,rgba(255,255,255,0.02));padding:14px;border-radius:12px">
          <strong>Community work</strong>
          <p style="color:var(--muted);margin:8px 0">Workshops and short-series support local groups exploring scent for presence and ritual.</p>
        </div>

        <div style="display:flex;gap:8px;align-items:center">
          <a class="btn-ghost" href="pricing.html">See investment</a>
          <a class="btn-cta" href="book.html">Reserve a session</a>
        </div>
      </aside>
    </section>

    <section style="padding:28px">
      <h3>Proof & social notes</h3>
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:12px">
        <div style="background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;min-width:220px">"Grounded guidance, practical homework." — L.</div>
        <div style="background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;min-width:220px">"I learned how to test safely with my cat at home." — J.</div>
        <div style="background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;min-width:220px">"A lovely scent pairing for mornings." — T.</div>
      </div>
    </section>

    <section style="padding:28px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border-top:1px solid rgba(255,255,255,0.02)">
      <h3>FAQs — safety essentials</h3>
      <p style="color:var(--muted)"><strong>Patch tests:</strong> Always patch-test at home before full skin application. Wait 24 hours and watch for irritation.</p>
      <p style="color:var(--muted)"><strong>Dilution:</strong> You will receive clear dilution charts for topical use; facial and mucous contact is avoided unless specified.</p>
      <p style="color:var(--muted)"><strong>Pregnancy & medication:</strong> Mention pregnancy, breastfeeding, and medications during intake so blends can be adapted.</p>
      <p style="color:var(--muted)"><strong>Pets:</strong> Some oils are not pet-safe; alternatives and ventilation guidance are provided for shared spaces.</p>
    </section>

    <section style="padding:28px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <h3>Ready to begin a guided blend?</h3>
        <p style="color:var(--muted)">Start with a single Intensive or explore a seasonal plan. I meet clients locally and via virtual consults.</p>
      </div>
      <div>
        <a class="btn-cta" href="book.html">Book a consult</a>
      </div>
    </section>

  </main>

  <script>
    // Simple proof rotator with tooltips for badges
    (function(){
      var rotator = document.getElementById('proof-rotator');
      var quotes = ['"Simple, steady guidance." — P.','"Clear safety notes and pleasant blends." — A.','"I appreciated the follow-up adjustments." — M.'];
      var i=0;
      setInterval(function(){ rotator.textContent = quotes[i]; i=(i+1)%quotes.length; },4000);

      // small tooltip for first badge
      var badge = document.querySelector('.badge-mini');
      if(badge){
        badge.addEventListener('mouseenter',function(e){
          var tip = badge.querySelector('.tip'); if(tip) tip.style.display='block';
        });
        badge.addEventListener('mouseleave',function(e){
          var tip = badge.querySelector('.tip'); if(tip) tip.style.display='none';
        });
      }
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#061018;--card:#081a22;--accent:#b08a52;--muted:#98b3c1}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,var(--bg),#021015);color:#eaf6fb}
    header{display:flex;justify-content:space-between;padding:18px 26px}
    nav a{color:var(--muted);margin:0 10px;text-decoration:none}
    .hero{padding:26px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:22px}
    .card{background:linear-gradient(180deg,var(--card),rgba(255,255,255,0.01));padding:18px;border-radius:12px}
    label{display:block;margin-top:12px;color:var(--muted);font-size:14px}
    input,select,textarea{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:#eaf6fb}
    .btn-cta{background:var(--accent);color:#021015;padding:10px 14px;border-radius:8px;text-decoration:none;border:none;font-weight:700}
    .wheel{width:100%;height:300px;display:grid;place-items:center}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    .a-well{display:flex;gap:12px;align-items:center}
    .sect-desc{background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;color:var(--muted)}
    .tips{margin-top:14px;color:var(--muted)}
    @media(max-width:900px){.grid{grid-template-columns:1fr}}

    /* Aroma wheel styles */
    .wheel-svg{width:260px;height:260px}
    .wheel-seg{cursor:pointer;transition:transform .14s}
    .wheel-seg:hover{transform:scale(1.03)}
    .legend{display:flex;flex-direction:column;gap:8px}
    .legend button{background:transparent;border:1px solid rgba(255,255,255,0.03);color:var(--muted);padding:8px;border-radius:8px;cursor:pointer}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(145deg,#0b222a,var(--accent));display:grid;place-items:center;font-weight:700">AR</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Reserve a focused session</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Sanctum</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends Lab</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Who I Am</a>
      <a href="book.html" style="color:#fff;font-weight:700">Reserve</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main class="hero">
    <div class="grid">
      <div class="card">
        <h2>Reserve an Intensive</h2>
        <p class="note">Complete the request below to hold a session time. A deposit may be required to confirm.</p>
        <form id="booking-form">
          <label for="name">Full name</label>
          <input id="name" name="name" required />

          <label for="email">Email</label>
          <input id="email" name="email" type="email" required />

          <label for="phone">Phone</label>
          <input id="phone" name="phone" />

          <label for="type">Preferred session</label>
          <select id="type" name="type">
            <option>Essence Intensive (90–120 min)</option>
            <option>Seasonal Palette (3-session)</option>
            <option>Virtual consult (60 min)</option>
          </select>

          <label for="notes">Notes — medications, pregnancy, pets, or sensitivities</label>
          <textarea id="notes" name="notes" rows="4" placeholder="Share anything that helps guide safety and blend choices"></textarea>

          <div style="margin-top:14px;display:flex;gap:10px">
            <button class="btn-cta" type="button" id="submit-btn">Request time</button>
            <a class="btn-ghost" href="pricing.html" style="text-decoration:none;color:var(--muted);border:1px solid rgba(255,255,255,0.03);padding:10px;border-radius:8px">See plans</a>
          </div>
        </form>

        <div class="tips">
          <strong>Before we meet</strong>
          <p style="margin:6px 0;color:var(--muted)">Please note pregnancy, medication, and pet exposures in the intake so blends can be adapted. You will receive patch-test and dilution instructions prior to topical use.</p>
        </div>
      </div>

      <aside>
        <div class="card">
          <h3>Interactive Aroma Wheel</h3>
          <div class="wheel">
            <svg class="wheel-svg" viewBox="0 0 200 200" aria-hidden="true">
              <defs>
                <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#b08a52"/><stop offset="1" stop-color="#8a6b3f"/></linearGradient>
                <linearGradient id="g2" x1="0" x2="1"><stop offset="0" stop-color="#7fb3a7"/><stop offset="1" stop-color="#5f8f7f"/></linearGradient>
                <linearGradient id="g3" x1="0" x2="1"><stop offset="0" stop-color="#8fb0cf"/><stop offset="1" stop-color="#6b8aa8"/></linearGradient>
              </defs>
              <!-- base -->
              <path d="M100,100 L100,190 A90,90 0 0,1 10,100 z" class="wheel-seg" id="seg-base" fill="url(#g1)"/>
              <!-- middle -->
              <path d="M100,100 L10,100 A50,50 0 0,1 100,50 z" class="wheel-seg" id="seg-middle" fill="url(#g2)"/>
              <!-- top -->
