  <script>
    // Booking button behavior (local only)
    document.getElementById('submit-btn').addEventListener('click',function(){
      var name=document.getElementById('name').value; var email=document.getElementById('email').value;
      if(!name||!email){ alert('Please provide name and email to request a time.'); return; }
      this.disabled=true; this.textContent='Request sent';
      setTimeout(()=>{ alert('Thanks — a booking request was sent. We will follow up via email.'); },300);
    });

    // Aroma wheel interactions
    var descBox = document.getElementById('desc-box');
    var notes = {
      top: 'Top notes — Bright, volatile: citrus, light herbs. Quick impression and lift; often first perceived. Typical examples: lemon, bergamot, peppermint. Use: brief inhalations, diffusing for short bursts.',
      middle: 'Middle notes — The heart of a blend: floral, spice, and green accords. They bridge top and base; include lavender, geranium, rosemary. Use: body of a roll-on or blend for mood support.',
      base: 'Base notes — Deep, lingering scents: resins and woods. They anchor blends and may increase longevity. Examples: cedarwood, vetiver, benzoin. Use: small amounts; often blended with carrier oils.'
    };

    function setDesc(k){ descBox.textContent = notes[k] || 'Hover segments to see notes'; }

    document.getElementById('seg-top').addEventListener('mouseenter',function(){ setDesc('top'); });
    document.getElementById('seg-middle').addEventListener('mouseenter',function(){ setDesc('middle'); });
    document.getElementById('seg-base').addEventListener('mouseenter',function(){ setDesc('base'); });
    // touch / click support for mobile
    ['seg-top','seg-middle','seg-base'].forEach(function(id){
      document.getElementById(id).addEventListener('click',function(){
        if(id==='seg-top') setDesc('top'); if(id==='seg-middle') setDesc('middle'); if(id==='seg-base') setDesc('base');
      });
    });

    // legend buttons
    document.querySelectorAll('[data-target]').forEach(function(btn){
      btn.addEventListener('click',function(){ setDesc(this.getAttribute('data-target')); });
    });
  </script>
